'use strict';
let marketScope='all',marketQuery='',marketStatus='전체',marketFrom='',marketTo='',mallEditorTab='overview',marketVariant='',checkoutCoupon='',productSelection=new Set(),mallFilters={},marketSort='추천순';
const merchantActor=()=>({role:db.role,org:db.orgId});
const canOperate=()=>['agency','admin'].includes(db.role);
const selectedStore=()=>db.role==='agency'?db.orgId:marketScope==='all'?db.orgId:marketScope;
const merchantOrgIds=()=>db.role==='agency'?[db.orgId]:marketScope==='all'?db.orgs.map(o=>o.id):[marketScope];
const isManagedOrg=id=>MarketCore.permitted(merchantActor(),id);
const shopSettings=id=>db.market.shops[id];
const productPhoto=p=>p.imageUploadId&&uploadedImages.has(p.imageUploadId)?uploadedImages.get(p.imageUploadId):asset(p.image||'hero');
const itemPhoto=i=>i.imageUploadId&&uploadedImages.has(i.imageUploadId)?uploadedImages.get(i.imageUploadId):asset(i.image||'hero');
const publicProducts=id=>db.products.filter(p=>(!id||p.org===id)&&MarketCore.publicProduct(db,p));
const categoryPath=p=>MarketCore.ancestors(db,p.org,p.categoryId).map(c=>c.name).join(' › ');
const field=(label,name,value='',type='text',extra='')=>`<label class="field">${label}<input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;
const selectField=(label,name,options,selected='',extra='')=>`<label class="field">${label}<select name="${name}" ${extra}>${options.map(([value,text])=>`<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
const note=(text,warn=false)=>`<div class="info-box ${warn?'warn':''}">${icon('info')}<span>${text}</span></div>`;
function guarded(action){try{const result=action();save();render();return result}catch(error){toast(error.message);return null}}
function scopedProductList(){return db.products.filter(p=>merchantOrgIds().includes(p.org)&&(!marketQuery||(p.name+' '+p.sku+' '+org(p.org).name+' '+p.brand).toLowerCase().includes(marketQuery.toLowerCase()))&&(marketStatus==='전체'||marketStatus==='품절'&&p.stock===0||p.saleStatus===marketStatus))}
function scopedOrderRows(){return MarketCore.orderRows(db,merchantActor(),db.role==='agency'?db.orgId:marketScope).filter(r=>(!marketQuery||(r.orderId+' '+r.name+' '+r.items.map(i=>i.name).join(' ')+' '+r.fulfillment.tracking).toLowerCase().includes(marketQuery.toLowerCase()))&&(marketStatus==='전체'||r.fulfillment.status===marketStatus)&&(!marketFrom||r.createdAt.slice(0,10)>=marketFrom)&&(!marketTo||r.createdAt.slice(0,10)<=marketTo))}
function categoryOptions(orgId,exclude=null){const list=MarketCore.categories(db,orgId),rows=[];const walk=(parent,depth)=>{for(const c of list.filter(c=>c.parent===parent)){if(exclude&&MarketCore.descendants(db,orgId,exclude).has(c.id))continue;rows.push([c.id,'　'.repeat(depth)+(depth?'└ ':'')+c.name+(c.visible?'':' (숨김)')]);walk(c.id,depth+1)}};walk(null,0);return rows}
function scopePanel(){if(!canOperate())return '';const isAdmin=db.role==='admin',orgIds=merchantOrgIds();return `<div class="merchant-scope-panel"><div class="merchant-scope-icon">${icon(isAdmin?'building':'shop')}</div><div class="merchant-scope-copy"><small>${isAdmin?'INSTITUTION WORKSPACE':'MY STORE WORKSPACE'}</small><strong>${isAdmin?(marketScope==='all'?'전체 기관 통합 관리':esc(org(marketScope).name)):esc(org(db.orgId).name)}</strong></div>${isAdmin?`<select id="merchant-scope" aria-label="관리 기관 선택"><option value="all" ${marketScope==='all'?'selected':''}>전체 기관</option>${db.orgs.map(o=>`<option value="${o.id}" ${marketScope===o.id?'selected':''}>${esc(o.name)}</option>`).join('')}</select>`:`<a href="#/institution/${db.orgId}" class="pill-btn">쇼핑몰 보기</a>`}</div>`}
function filterBar(kind){const statuses=kind==='products'?['전체','판매 중','품절','판매 중지','임시 저장']:kind==='claims'?['전체','접수 대기','승인','처리 완료','접수 철회']:['전체','신규 주문','상품 준비 중','배송 중','배송 완료','구매 확정','취소 완료','반품 완료'];return `<form class="merchant-filter" id="merchant-search-form"><div class="merchant-search">${icon('search')}<input name="query" aria-label="관리 내역 검색" placeholder="${kind==='products'?'상품명 · SKU · 기관 검색':'주문번호 · 상품 · 수령인 검색'}" value="${esc(marketQuery)}"><button aria-label="검색">${icon('arrow')}</button></div><div class="merchant-filter-row"><select id="merchant-status" aria-label="관리 상태 필터">${statuses.map(s=>`<option ${s===marketStatus?'selected':''}>${s}</option>`).join('')}</select>${kind!=='products'&&kind!=='claims'?`<input type="date" name="from" aria-label="조회 시작일" value="${marketFrom}"><span>–</span><input type="date" name="to" aria-label="조회 종료일" value="${marketTo}">`:''}${btn('merchant-filter-reset','초기화','pill-btn')}</div></form>`}
function pickStoreNotice(title){return consoleTitle(title,'기관마다 독립적으로 설정할 수 있습니다.')+empty('관리할 기관을 선택해 주세요','위의 기관 선택에서 한 기관을 고르면<br>해당 기관의 설정과 카테고리를 관리할 수 있습니다.',btn('pick-first-store','첫 번째 기관 관리하기','primary-btn green'))}
function merchantDashboard(){const rows=scopedOrderRows(),ps=scopedProductList(),active=rows.filter(r=>!['취소 완료','반품 완료'].includes(r.fulfillment.status)),revenue=active.reduce((n,r)=>n+r.merchandise,0),waiting=rows.filter(r=>['신규 주문','상품 준비 중'].includes(r.fulfillment.status)).length;const claims=db.market.claims.filter(c=>merchantOrgIds().includes(c.org)&&!['처리 완료','접수 철회'].includes(c.status));return `<div class="merchant-dashboard-intro"><span class="section-overline">TODAY IN YOUR STORE</span><h2>좋은 상품, 기분 좋은 운영.</h2><p>상품과 주문, 고객의 이야기를 한곳에서 관리하세요.</p></div><div class="stat-grid">${statCard('판매 상품',ps.filter(p=>p.saleStatus==='판매 중').length+'개','품절 '+ps.filter(p=>p.stock===0).length+'개',true)}${statCard('누적 상품 판매액',won(revenue),'배송비 제외 · 체험 주문')}${statCard('주문 처리 대기',waiting+'건','주문 접수와 출고 준비')}${statCard('교환·반품 대기',claims.length+'건','확인이 필요한 요청')}</div><div class="merchant-task-grid">${[['orders','box','신규 주문',rows.filter(r=>r.fulfillment.status==='신규 주문').length],['shipping','truck','출고 준비',rows.filter(r=>r.fulfillment.status==='상품 준비 중').length],['inventory','bag','재고 5개 이하',ps.filter(p=>p.stock<=5).length],['customers','people','답변 대기',db.market.inquiries.filter(q=>merchantOrgIds().includes(q.org)&&q.status==='답변 대기').length]].map(([section,i,label,n])=>btn('merchant-section',icon(i)+`<strong>${n}</strong><span>${label}</span>`,'merchant-task',`data-section="${section}"`)).join('')}</div><div class="merchant-quick-actions">${btn('product-new',icon('box')+' 상품 등록','primary-btn green')}${btn('merchant-section',icon('shop')+' 쇼핑몰 디자인','secondary-btn','data-section="mall"')}${btn('merchant-section',icon('chart')+' 판매 분석','secondary-btn','data-section="sales"')}</div>${consoleTitle('최근 주문','기관별 상품과 배송 상태를 한눈에 확인합니다.')} ${merchantOrderList(rows.slice(0,4))}<div class="merchant-section-gap"></div>${consoleTitle('최근 운영 기록')}<div class="activity-feed">${db.market.audit.filter(a=>!a.org||merchantOrgIds().includes(a.org)).slice(0,6).map(a=>`<div><span class="activity-point"></span><p><b>${esc(a.type)}</b> ${esc(a.text)}<small>${new Date(a.at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})}</small></p></div>`).join('')||'<p class="small muted">상품·카테고리·주문을 관리하면 최근 기록이 여기에 쌓입니다.</p>'}</div>`}
function merchantProducts(inventory=false){const ps=scopedProductList();return consoleTitle(inventory?'기관별 재고 관리':'판매 상품 관리','가격·옵션·재고·판매 상태를 함께 관리하세요.',btn('product-new','+ 상품 등록','pill-btn'))+filterBar('products')+`<div class="merchant-list-summary"><span>조회된 상품 <b>${ps.length}</b>개</span>${btn('merchant-export',icon('download')+' CSV','pill-btn','data-kind="products"')}</div><div class="bulk-product-bar"><label><input id="product-select-all" type="checkbox" ${ps.length&&ps.every(p=>productSelection.has(p.id))?'checked':''}> 전체 선택</label><span>${ps.filter(p=>productSelection.has(p.id)).length}개 선택</span><select id="bulk-product-action" aria-label="상품 일괄 작업"><option value="">일괄 작업 선택</option><option value="판매 중">판매 시작</option><option value="판매 중지">판매 중지</option><option value="임시 저장">임시 저장으로</option><option value="recommend">추천 상품 지정</option><option value="category">카테고리 이동</option></select>${btn('product-bulk','적용','pill-btn')}</div><div class="data-list product-operation-list">${ps.map(p=>`<article class="data-row"><input type="checkbox" class="product-row-check" data-id="${p.id}" aria-label="${esc(p.name)} 선택" ${productSelection.has(p.id)?'checked':''}><img src="${productPhoto(p)}" alt="${esc(p.name)}"><div class="data-row-content"><p>${esc(org(p.org).name)} · ${esc(p.sku)}</p><h3>${esc(p.name)}</h3><p>${esc(categoryPath(p))}</p><strong>${won(p.price)}</strong><p>재고 ${p.stock}개${p.variants.length?' · 옵션 '+p.variants.length+'종':''}${p.recommended?' · 추천 상품':''}</p></div><div class="data-row-side">${status(p.stock===0&&p.saleStatus==='판매 중'?'품절':p.saleStatus)}${btn('product-edit',inventory?'재고·옵션':'상품 수정','',`data-id="${p.id}"`)}<a class="text-link" href="#/product/${p.id}">미리보기</a></div></article>`).join('')||empty('조건에 맞는 상품이 없어요','필터를 바꾸거나 새 상품을 등록해 주세요.')}</div>`}
function variantRow(v={}){return `<div class="variant-editor-row" data-id="${v.id||''}"><input name="variantLabel" aria-label="옵션 이름" placeholder="예: 화이트 / M" value="${esc(v.label||'')}" maxlength="60"><input name="variantExtra" aria-label="옵션 추가 금액" type="number" min="0" step="1" placeholder="추가금" value="${v.extra||0}"><input name="variantStock" aria-label="옵션 재고" type="number" min="0" max="100000" placeholder="재고" value="${v.stock||0}">${btn('variant-remove',icon('close'),'icon-btn','aria-label="옵션 삭제"')}</div>`}
function merchantProductModal(id,donationId){const donation=db.donations.find(d=>d.id===donationId);if(donation&&!isManagedOrg(donation.org))return;const old=product(id);if(old&&!isManagedOrg(old.org)){toast('이 기관의 상품을 관리할 수 없습니다.');return}const orgId=old?.org||donation?.org||selectedStore(),p=old||{org:orgId,name:donation?.name||'',price:'',original:'',sku:'',brand:'',stock:donation?.qty||1,categoryId:MarketCore.categories(db,orgId)[0]?.id,image:'hero',saleStatus:'임시 저장',condition:'새 상품',summary:'',desc:'',variants:[],donor:donation?.donor||'',recommended:false,deliveryNote:''};openModal(id?'판매 상품 수정':'새 판매 상품 등록',`<form id="merchant-product-form" data-id="${id||''}" data-donation="${donationId||''}" data-image-upload="${p.imageUploadId||''}"><div class="editor-section-label">01 기본 정보</div>${db.role==='admin'?selectField('판매 기관','org',db.orgs.map(o=>[o.id,o.name]),p.org,'id="product-merchant"'):`<input type="hidden" name="org" value="${p.org}">`}${field('상품명','name',p.name,'text','required maxlength="100"')}${selectField('쇼핑몰 카테고리','categoryId',categoryOptions(p.org),p.categoryId,'id="product-category" required')}<div class="field-row">${field('상품 코드 (SKU)','sku',p.sku,'text','maxlength="40"')}${field('브랜드·제조사','brand',p.brand,'text','maxlength="40"')}</div><div class="editor-section-label">02 가격과 재고</div><div class="field-row">${field('판매가 (원)','price',p.price,'number','min="1" step="1" required')}${field('정상가 (원)','original',p.original,'number','min="1" step="1" required')}</div>${field('기본 재고','stock',p.stock,'number','min="0" max="100000" required')}<div class="variant-editor"><div class="split-row"><label>상품 옵션</label>${btn('variant-add','+ 옵션 추가','pill-btn')}</div><p>옵션을 등록하면 옵션별 재고의 합계가 상품 재고가 됩니다.</p><div id="variant-editor-rows">${p.variants.filter(v=>!v.retired).map(variantRow).join('')}</div></div><div class="editor-section-label">03 이미지와 상품 소개</div><div class="product-upload-preview"><img id="merchant-product-image" src="${productPhoto(p)}" alt="상품 대표 이미지"><div>${selectField('샘플 이미지','image',[['hero','기부 상품 상자'],['knit','그래픽 티셔츠'],['mug','도자기 머그'],['tote','데일리 가방'],['serum','스킨케어 세트'],['lamp','테이블 조명'],['book','도서'],['objects','리빙 상품 모음']],p.image,'id="merchant-image-sample"')}<label class="pill-btn image-upload-label">대표 이미지 업로드<input id="merchant-product-upload" type="file" accept="image/jpeg,image/png,image/webp" aria-label="상품 대표 이미지 업로드"></label></div></div>${field('짧은 소개','summary',p.summary,'text','maxlength="100"')}<label class="field">상품 상세 설명<textarea name="desc" maxlength="2000" rows="5">${esc(p.desc)}</textarea></label><div class="field-row">${field('상품 상태','condition',p.condition,'text','maxlength="50"')}${field('기부자·공급처 (선택)','donor',p.donor,'text','maxlength="60"')}</div>${field('상품별 배송 안내','deliveryNote',p.deliveryNote,'text','maxlength="150"')}<div class="editor-section-label">04 판매와 진열</div>${selectField('판매 상태','saleStatus',[['판매 중','판매 중'],['판매 중지','판매 중지'],['임시 저장','임시 저장']],p.saleStatus)}<label class="check-line"><input name="recommended" type="checkbox" ${p.recommended?'checked':''}>기관몰 추천 상품으로 진열</label><div class="sticky-form-actions">${btn('close-modal','취소','secondary-btn')}<button class="primary-btn green">상품 저장</button></div></form>`,true)}
function merchantCategories(){if(db.role==='admin'&&marketScope==='all')return pickStoreNotice('기관별 쇼핑몰 카테고리');const orgId=selectedStore(),list=MarketCore.categories(db,orgId);const rows=[];const walk=(parent,depth)=>list.filter(c=>c.parent===parent).forEach(c=>{rows.push(`<div class="category-operation-row" style="--category-depth:${depth}"><span class="category-tree-line"></span><div><span class="category-level">${depth+1}차 분류</span><strong>${esc(c.name)}</strong><small>상품 ${db.products.filter(p=>p.org===orgId&&MarketCore.descendants(db,orgId,c.id).has(p.categoryId)).length}개</small></div><span class="status ${c.visible?'':'gray'}">${c.visible?'노출':'숨김'}</span><div class="category-row-buttons">${btn('category-move','↑','',`data-id="${c.id}" data-direction="-1" aria-label="${esc(c.name)} 위로"`)}${btn('category-move','↓','',`data-id="${c.id}" data-direction="1" aria-label="${esc(c.name)} 아래로"`)}${btn('category-edit','수정','',`data-id="${c.id}"`)}${btn('category-delete',icon('close'),'',`data-id="${c.id}" aria-label="${esc(c.name)} 삭제"`)}</div></div>`);walk(c.id,depth+1)});walk(null,0);return consoleTitle('우리 쇼핑몰의 카테고리','대분류·중분류·소분류를 3단계로 구성하고 순서를 바꿔 보세요.',btn('category-new','+ 분류 추가','pill-btn'))+`<div class="category-tree">${rows.join('')||empty('카테고리를 만들어 보세요','상품을 나눌 분류를 추가할 수 있어요.')}</div>`+note('숨김 처리한 카테고리와 그 아래 상품은 쇼핑몰에 표시되지 않습니다. 상품이 있거나 하위 분류가 있는 카테고리는 이동 후 삭제할 수 있습니다.')}
function categoryModal(id){const orgId=selectedStore(),c=MarketCore.categories(db,orgId).find(c=>c.id===id)||{name:'',parent:null,visible:true};openModal(id?'카테고리 수정':'새 카테고리 만들기',`<form id="category-form" data-id="${id||''}" data-org="${orgId}">${field('카테고리 이름','name',c.name,'text','required maxlength="30"')}${selectField('상위 카테고리','parent',[['','최상위 대분류'],...categoryOptions(orgId,id)],c.parent||'')}<label class="check-line"><input type="checkbox" name="visible" ${c.visible?'checked':''}>쇼핑몰에 노출하기</label><button class="primary-btn green full">카테고리 저장</button></form>`)}
function merchantOrderList(rows){return rows.length?`<div class="data-list merchant-order-list">${rows.map(r=>`<article class="data-row"><img src="${itemPhoto(r.items[0])}" alt="주문 상품"><div class="data-row-content"><p>${esc(r.orderId)} · ${esc(r.date)}</p><h3>${esc(r.items[0].name)}${r.items.length>1?' 외 '+(r.items.length-1)+'종':''}</h3><p>${esc(org(r.org).name)} · ${esc(r.name)}<br>${r.fulfillment.tracking?esc(r.fulfillment.carrier)+' '+esc(r.fulfillment.tracking):'운송장 미등록'}</p><strong>${won(r.total)}</strong></div><div class="data-row-side">${status(r.fulfillment.status)}${btn('merchant-order-detail','주문·배송 관리','',`data-order="${r.orderId}" data-org="${r.org}"`)}</div></article>`).join('')}</div>`:empty('조회된 주문이 없습니다','기관·상태·기간을 바꾸거나 상품 주문을 체험해 보세요.')}
function merchantOrders(shipping=false){return consoleTitle(shipping?'주문별 배송과 운송장 관리':'기관별 주문 관리','기관별 주문 상품과 수령인, 배송 상태를 확인하세요.',btn('merchant-export',icon('download')+' CSV','pill-btn','data-kind="orders"'))+filterBar('orders')+(shipping?`<div class="event-mini"><strong>여러 주문의 운송장을 한 번에 등록해 보세요.</strong>주문을 확인하고 기관별로 출고 상태를 관리합니다.<div class="mt-20">${btn('bulk-shipping','운송장 일괄 등록','secondary-btn')}</div></div>`:'')+`<div class="merchant-list-summary">조회된 기관 주문 <b>${scopedOrderRows().length}건</b></div>`+merchantOrderList(scopedOrderRows())}
function orderEditor(orderId,orgId){try{const {order,f,items}=MarketCore.fulfillment(db,merchantActor(),orderId,orgId);openModal('주문과 배송 관리',`<div class="order-detail-id"><span>${esc(org(orgId).name)}</span><strong>${esc(order.id)}</strong>${status(f.status)}</div><div class="order-detail-items">${items.map(i=>`<div><img src="${itemPhoto(i)}" alt="${esc(i.name)}"><p><b>${esc(i.name)}</b><small>${esc(i.variantLabel)} · ${i.qty}개</small><strong>${won(i.unitPrice*i.qty-i.discount)}</strong></p></div>`).join('')}</div><div class="receipt-info-lines"><span>수령인 <b>${esc(order.name)}</b></span><span>연락처 <b>${esc(order.phone||'체험 번호 미입력')}</b></span><span>배송지 <b>${esc(order.address)}</b></span><span>배송 요청 <b>${esc(order.memo||'없음')}</b></span><span>배송비 <b>${won(f.shipping)}</b></span></div><form id="merchant-order-form" data-order="${orderId}" data-org="${orgId}">${selectField('주문 진행 상태','status',[[f.status,f.status],...(MarketCore.statusFlow[f.status]||[]).map(s=>[s,s])],f.status)}<div class="field-row">${selectField('택배사','carrier',['CJ대한통운','우체국택배','롯데택배','한진택배','로젠택배','직접 배송'].map(s=>[s,s]),f.carrier)}${field('운송장 번호','tracking',f.tracking,'text','maxlength="40"')}</div><label class="field">운영 메모<textarea name="note" maxlength="300">${esc(f.note)}</textarea></label><button class="primary-btn green full">주문·배송 저장</button></form><div class="button-group mt-20">${btn('merchant-claim-new','취소·교환·반품 접수','secondary-btn',`data-order="${orderId}" data-org="${orgId}"`)}</div>${note('배송 상태와 운송장은 이 브라우저의 체험 주문에 반영됩니다. 실제 택배 접수·결제 취소·환불은 연동 전입니다.')}`,true)}catch(error){toast(error.message)}}
function merchantSales(){const rows=scopedOrderRows(),valid=rows.filter(r=>!['취소 완료','반품 완료'].includes(r.fulfillment.status)),gross=valid.reduce((n,r)=>n+r.merchandise,0),confirmed=valid.filter(r=>r.fulfillment.status==='구매 확정');const groups=merchantOrgIds().map(id=>({id,rows:valid.filter(r=>r.org===id)}));return consoleTitle('판매 흐름을 한눈에','주문 시점의 상품 가격과 기관 정보를 기준으로 집계합니다.',btn('merchant-export',icon('download')+' CSV','pill-btn','data-kind="sales"'))+filterBar('orders')+`<div class="stat-grid">${statCard('상품 판매액',won(gross),'취소·반품 완료 제외',true)}${statCard('주문 건수',valid.length+'건','기관별 주문 기준')}${statCard('구매 확정액',won(confirmed.reduce((n,r)=>n+r.merchandise,0)),'정산 가능 판매금액')}${statCard('평균 주문 금액',won(valid.length?Math.round(gross/valid.length):0),'상품 판매액 기준')}</div><div class="report-card"><h3>기관별 판매금액</h3>${groups.map(g=>{const total=g.rows.reduce((n,r)=>n+r.merchandise,0);return `<div class="sales-bar-row"><div><span>${esc(org(g.id).name)}</span><strong>${won(total)}</strong></div><div class="progress-track"><span style="width:${gross?Math.max(2,total/gross*100):0}%"></span></div></div>`}).join('')}</div><div class="report-card"><h3>상품별 판매 순위</h3><div class="metrics-list">${db.products.filter(p=>merchantOrgIds().includes(p.org)).map(p=>({p,qty:valid.flatMap(r=>r.items).filter(i=>i.id===p.id).reduce((n,i)=>n+i.qty,0)})).sort((a,b)=>b.qty-a.qty).slice(0,8).map(({p,qty})=>`<div><span>${esc(p.name)}</span><strong>${qty}개</strong></div>`).join('')}</div></div>`}
function merchantClaims(){const list=db.market.claims.filter(c=>merchantOrgIds().includes(c.org)&&(marketStatus==='전체'||c.status===marketStatus)&&(!marketQuery||(c.orderId+c.reason).includes(marketQuery)));return consoleTitle('취소·교환·반품 관리','요청 사유를 확인하고 접수·승인·처리 완료를 관리하세요.')+filterBar('claims')+`<div class="data-list">${list.map(c=>`<div class="data-row">${icon(c.type==='교환'?'box':'truck')}<div class="data-row-content"><p>${esc(c.orderId)} · ${esc(org(c.org).name)}</p><h3>${esc(c.type)} 요청 · ${esc(c.reason)}</h3><p>${new Date(c.date).toLocaleDateString('ko-KR')}</p></div><div class="data-row-side">${status(c.status)}${btn('claim-process','요청 관리','',`data-id="${c.id}"`)}</div></div>`).join('')||empty('접수된 요청이 없어요','구매자 주문 상세 또는 주문 관리에서 접수할 수 있습니다.')}</div>`+note('취소·반품 완료 시 재고가 한 번만 복구됩니다. 정산 후 반품은 차기 정산 조정 내역으로 기록합니다. 실제 환불·택배 회수는 연동 전입니다.')}
function claimModal(orderId,orgId,buyer=false){const order=db.orders.find(o=>o.id===orderId),f=order?.fulfillments.find(f=>f.org===orgId);if(!order||!f)return;const types=['신규 주문','상품 준비 중'].includes(f.status)?['취소']:['반품','교환'];openModal('취소·교환·반품 신청',`<p>${esc(org(orgId).name)} · ${esc(order.id)}</p><form id="claim-create-form" data-order="${orderId}" data-org="${orgId}" data-buyer="${buyer}">${selectField('요청 유형','type',types.map(s=>[s,s]),types[0])}<label class="field">요청 사유<textarea name="reason" required maxlength="500" placeholder="요청 내용을 남겨 주세요."></textarea></label><button class="primary-btn green full">요청 접수</button></form>`)}
function claimProcess(id){const c=db.market.claims.find(c=>c.id===id);if(!c||!isManagedOrg(c.org))return;openModal(c.type+' 요청 관리',`<div class="report-card"><h3>${esc(c.orderId)}</h3><p>${esc(org(c.org).name)}<br>${esc(c.reason)}</p>${status(c.status)}</div><div class="button-group">${c.status==='접수 대기'?btn('claim-state','요청 승인','primary-btn green',`data-id="${id}" data-state="승인"`):''}${c.status==='승인'?btn('claim-state','처리 완료','primary-btn green',`data-id="${id}" data-state="처리 완료"`):''}${['접수 대기','승인'].includes(c.status)?btn('claim-state','접수 철회','secondary-btn',`data-id="${id}" data-state="접수 철회"`):''}</div>${note('체험 주문 상태만 변경됩니다. 실제 환불이나 회수 접수는 진행되지 않습니다.')}`)}
function merchantSettlements(){const ids=merchantOrgIds(),ss=db.settlements.filter(s=>ids.includes(s.org)),pending=MarketCore.orderRows(db,merchantActor(),db.role==='agency'?db.orgId:marketScope).filter(r=>r.fulfillment.status==='구매 확정'&&!r.fulfillment.settlementId),adjustments=db.market.adjustments.filter(a=>ids.includes(a.org)&&a.status==='미반영');return consoleTitle('판매 결과와 기관 정산','구매 확정 상품 금액을 기준으로 정산 대상을 생성합니다.',btn('merchant-export',icon('download')+' CSV','pill-btn','data-kind="settlements"'))+`<div class="stat-grid">${statCard('정산 생성 가능',won(pending.reduce((n,r)=>n+r.merchandise,0)),'구매 확정 · 미정산',true)}${statCard('정산 후 조정',won(adjustments.reduce((n,a)=>n+a.amount,0)),'취소·반품 차감 대기')}</div><div class="merchant-quick-actions">${btn('settlement-generate','구매 확정 주문으로 정산 생성','primary-btn green')}</div><div class="data-list">${ss.map(s=>`<div class="data-row"><div class="data-row-content"><p>${esc(s.id)} · ${esc(s.period)}</p><h3>${esc(org(s.org).name)}</h3><strong>${won(s.net)}</strong><p>상품 ${won(s.gross)} − 운영 비용 ${won(s.fee)}${s.adjustment?' · 조정 '+won(s.adjustment):''}<br>${s.orderRefs?'구매 확정 '+s.orderRefs.length+'건':'기존 기간 정산 · 예시 내역'}</p></div><div class="data-row-side">${status(s.status)}${btn('merchant-settlement-detail',s.status==='정산 완료'?'명세서':'정산 확인','',`data-id="${s.id}"`)}</div></div>`).join('')}</div>${note('정산 생성 시 동일한 주문이 중복 포함되지 않도록 연결합니다. 실제 계좌 송금은 연결 전입니다.')}`}
function merchantCoupons(){const list=db.market.coupons.filter(c=>!c.org&&db.role==='admin'||merchantOrgIds().includes(c.org));return consoleTitle('쿠폰과 구매 혜택','기관별 쿠폰의 할인율·사용 기간·최소 주문액을 설정하세요.',btn('coupon-new','+ 쿠폰 만들기','pill-btn'))+`<div class="coupon-grid">${list.map(c=>`<article class="coupon-card"><div><span>${c.org?esc(org(c.org).name):'모든 기관 공통'}</span><strong>${c.type==='percent'?c.amount+'%':won(c.amount)}</strong><h3>${esc(c.name)}</h3><code>${esc(c.code)}</code></div><aside>${status(c.active?'사용 중':'사용 중지')}<small>${c.expires}까지<br>${c.used} / ${c.limit}회 사용</small>${btn('coupon-edit','쿠폰 수정','pill-btn',`data-id="${c.id}"`)}</aside></article>`).join('')||empty('등록된 쿠폰이 없어요','상품 구매 체험에 사용할 쿠폰을 만들어 보세요.')}</div>`}
function couponModal(id){const c=db.market.coupons.find(c=>c.id===id);if(c&&(c.org?!isManagedOrg(c.org):db.role!=='admin'))return;const v=c||{org:selectedStore(),name:'',code:'',type:'percent',amount:10,min:20000,max:5000,limit:100,expires:'2027-12-31',active:true};openModal(id?'쿠폰 설정 수정':'새 쿠폰 만들기',`<form id="merchant-coupon-form" data-id="${id||''}">${db.role==='admin'?selectField('사용 기관','org',[['','전체 기관 공통'],...db.orgs.map(o=>[o.id,o.name])],v.org):`<input type="hidden" name="org" value="${db.orgId}">`}${field('쿠폰 이름','name',v.name,'text','required maxlength="50"')}${field('쿠폰 코드','code',v.code,'text','required maxlength="20" pattern="[A-Za-z0-9_-]+"')}<div class="field-row">${selectField('할인 방식','type',[['percent','비율 할인 (%)'],['fixed','금액 할인 (원)']],v.type)}${field('할인 값','amount',v.amount,'number','min="1" required')}</div><div class="field-row">${field('최소 상품 주문액','min',v.min,'number','min="0" required')}${field('최대 할인액 · 0은 제한 없음','max',v.max,'number','min="0" required')}</div><div class="field-row">${field('사용 종료일','expires',v.expires,'date','required')}${field('최대 사용 수량','limit',v.limit,'number','min="1" required')}</div><label class="check-line"><input type="checkbox" name="active" ${v.active?'checked':''}>사용 가능 상태로 설정</label><button class="primary-btn green full">쿠폰 저장</button></form>`,true)}
function merchantCustomers(){const list=db.market.inquiries.filter(q=>merchantOrgIds().includes(q.org));return consoleTitle('고객과 상품 문의','기관별 문의를 확인하고 답변을 남겨 주세요.')+`<div class="stat-grid">${statCard('답변 대기',list.filter(q=>q.status==='답변 대기').length+'건','고객의 질문을 확인해 주세요',true)}${statCard('답변 완료',list.filter(q=>q.status==='답변 완료').length+'건','남겨 둔 답변 내역')}</div><div class="data-list">${list.map(q=>`<div class="data-row">${icon('people')}<div class="data-row-content"><p>${esc(org(q.org).name)} · ${esc(q.name)}</p><h3>${esc(q.title)}</h3><p>${esc(q.body)}</p></div><div class="data-row-side">${status(q.status)}${btn('inquiry-answer','문의·답변','',`data-id="${q.id}"`)}</div></div>`).join('')||empty('문의가 아직 없어요','상품 상세에서 문의를 남기면 이곳에서 확인할 수 있습니다.')}</div>`}
function inquiryAnswer(id){const q=db.market.inquiries.find(q=>q.id===id);if(!q||!isManagedOrg(q.org))return;openModal('고객 문의 답변',`<div class="report-card"><h3>${esc(q.title)}</h3><p>${esc(q.body)}</p><small>${esc(q.name)} · ${esc(q.date)}</small></div><form id="merchant-inquiry-form" data-id="${id}"><label class="field">답변<textarea name="answer" required maxlength="1000">${esc(q.answer)}</textarea></label><button class="primary-btn green full">답변 저장</button></form>`)}
function merchantInstitutions(){return consoleTitle('기관별 쇼핑몰 운영 현황','상품과 주문, 쇼핑몰 설정을 기관별로 바로 확인하세요.')+`<div class="institution-operation-grid">${db.orgs.map(o=>{const ps=db.products.filter(p=>p.org===o.id),rows=MarketCore.orderRows(db,{role:'admin'},o.id);return `<article class="institution-operation-card"><div class="split-row"><div class="mall-identity"><span class="org-logo-fixed" style="color:${o.color}">${o.symbol}</span><div><small>${esc(o.area)}</small><h3>${esc(o.name)}</h3></div></div>${status(shopSettings(o.id).status)}</div><div class="institution-card-metrics"><span>상품 <b>${ps.length}</b></span><span>주문 <b>${rows.length}</b></span><span>출고 대기 <b>${rows.filter(r=>r.fulfillment.status==='상품 준비 중').length}</b></span></div><div class="button-group">${btn('institution-open','쇼핑몰 설정','secondary-btn',`data-id="${o.id}" data-section="mall"`)}${btn('institution-open','상품·주문 관리','secondary-btn',`data-id="${o.id}" data-section="orders"`)}<a class="pill-btn" href="#/institution/${o.id}">기관몰 보기</a></div></article>`}).join('')}</div>`}
function merchantMallManager(){if(db.role==='admin'&&marketScope==='all')return pickStoreNotice('기관별 쇼핑몰 설정');const id=selectedStore(),o=org(id),s=shopSettings(id);const tabs=[['overview','기본 정보'],['theme','테마·레이아웃'],['images','배너·여백'],['display','상품 진열'],['shipping','배송·정책']];return consoleTitle('기관 쇼핑몰 관리','기관의 상품과 이야기가 잘 보이는 쇼핑몰을 만들어 보세요.',`<a class="pill-btn" href="#/institution/${id}">미리보기 ${icon('arrow')}</a>`)+`<div class="shop-design-summary"><span class="org-logo-fixed" style="color:${o.color}">${o.symbol}</span><div><strong>${esc(o.name)}</strong><small>${MarketCore.themes[s.theme]?.label||'나만의 테마'} · ${s.layout==='compact'?'컴팩트 진열':'에디토리얼 진열'}</small></div>${status(s.status)}</div><div class="merchant-editor-tabs">${tabs.map(([key,label])=>btn('mall-editor-tab',label,mallEditorTab===key?'active':'',`data-tab="${key}"`)).join('')}</div>${mallEditorTab==='images'?`<div class="mall-banner-playlist"><h3>기관몰 배너 순환 설정</h3><p>최대 5개를 고르면 기관몰 상단에서 순서대로 보여 줍니다.</p><form id="mall-playlist-form" data-org="${id}"><div class="playlist-images">${designFor('org:'+id).banners.map(slot=>`<label><input type="checkbox" name="banners" value="${slot.id}" ${(s.bannerIds.length?s.bannerIds:[designFor('org:'+id).bannerId]).includes(slot.id)?'checked':''}><img src="${mediaSource(slot)}" alt="${esc(slot.label)}"><span>${esc(slot.label)}</span></label>`).join('')}</div><button class="secondary-btn full">배너 순환 목록 저장</button></form></div>${designManager('org:'+id,false)}`:mallEditorTab==='theme'?`<div class="theme-samples">${Object.entries(MarketCore.themes).map(([key,t])=>btn('shop-theme',`<div style="background:${t.surface}"><span style="background:${t.color}"></span><i></i><i></i></div><strong>${t.label}</strong>${s.theme===key?icon('check'):''}`,'theme-sample '+(s.theme===key?'active':''),`data-theme="${key}" data-org="${id}"`)).join('')}</div><form id="merchant-shop-form" data-org="${id}" data-kind="theme" class="form-box">${selectField('상품 진열 스타일','layout',[['editorial','에디토리얼 · 넉넉한 2열'],['compact','컴팩트 · PC 3열 / 모바일 2열']],s.layout)}${selectField('상품 카드 모서리','cardStyle',[['soft','부드러운 라운드'],['square','단정한 직선']],s.cardStyle)}${selectField('상단 배너 높이','bannerHeight',[[230,'컴팩트 · 230px'],[300,'기본 · 300px'],[360,'와이드 비주얼 · 360px']],s.bannerHeight)}<button class="primary-btn green full">레이아웃 저장</button></form>`:mallEditorTab==='display'?`<div class="section-order-editor"><h3>쇼핑몰 섹션 순서·노출</h3>${s.sectionOrder.map((key,i)=>`<div><label><input class="shop-section-check" type="checkbox" data-key="${key}" data-org="${id}" ${s.sectionVisible[key]?'checked':''}>${{featured:'추천 상품',products:'전체 판매 상품',story:'기관 이야기'}[key]}</label><span>${btn('shop-section-move','↑','pill-btn',`data-index="${i}" data-dir="-1" data-org="${id}"`)}${btn('shop-section-move','↓','pill-btn',`data-index="${i}" data-dir="1" data-org="${id}"`)}</span></div>`).join('')}</div><div class="form-box mt-20"><h3>추천 상품 설정</h3><p class="small muted">상품 관리에서 추천을 지정하거나 여기에서 바로 변경할 수 있습니다.</p>${db.products.filter(p=>p.org===id).map(p=>`<label class="check-line"><input class="shop-recommend-check" type="checkbox" data-id="${p.id}" ${p.recommended?'checked':''}>${esc(p.name)} · ${status(p.saleStatus)}</label>`).join('')}</div>`:mallEditorTab==='shipping'?`<form id="merchant-shop-form" data-org="${id}" data-kind="shipping" class="form-box"><div class="field-row">${field('기본 배송비 (원)','shippingFee',s.shippingFee,'number','min="0" required')}${field('무료 배송 기준 (원)','freeShipping',s.freeShipping,'number','min="0" required')}</div><p class="small muted">무료 배송 기준을 0으로 설정하면 무료 배송 기준을 적용하지 않습니다.</p>${field('출고 일정 안내','dispatchDays',s.dispatchDays,'text','required maxlength="100"')}${selectField('기본 택배사','carrier',['CJ대한통운','우체국택배','롯데택배','한진택배','로젠택배','직접 배송'].map(x=>[x,x]),s.carrier)}${field('왕복 교환·반품 배송비 (원)','returnFee',s.returnFee,'number','min="0" required')}${field('반품 주소·접수 안내','returnAddress',s.returnAddress,'text','required maxlength="200"')}<label class="field">배송·교환·반품 정책<textarea name="policy" maxlength="1000" required>${esc(s.policy)}</textarea></label><button class="primary-btn green full">배송·정책 저장</button></form>`:`<form id="merchant-shop-form" data-org="${id}" data-kind="overview" class="form-box">${field('기관 쇼핑몰 이름','name',o.name,'text','required maxlength="40"')}${field('상단 소개 문구','tagline',o.tag,'text','required maxlength="60"')}<label class="field">기관 소개<textarea name="description" required maxlength="1000">${esc(o.description)}</textarea></label>${field('활동 지역·분야','area',o.area,'text','required maxlength="50"')}${selectField('쇼핑몰 운영 상태','status',[['운영 중','운영 중'],['준비 중','준비 중 · 상품 비노출'],['일시 중지','일시 중지 · 상품 비노출']],s.status)}${field('고객센터 안내','phone',s.phone,'text','maxlength="100"')}${field('문의 운영 시간','hours',s.hours,'text','maxlength="100"')}${field('상단 공지 문구','announcement',s.announcement,'text','maxlength="150"')}<label class="check-line"><input type="checkbox" name="announcementOn" ${s.announcementOn?'checked':''}>쇼핑몰 상단에 공지 노출</label><button class="primary-btn green full">쇼핑몰 기본 정보 저장</button></form>`}`}
function mainManager(){const m=db.market.main;return consoleTitle('메인 페이지 운영 관리','섹션 순서와 추천 상품, 노출 기관을 직접 구성하세요.','<a class="pill-btn" href="#/">메인 미리보기</a>')+`<div class="section-order-editor"><h3>메인 섹션 순서·노출</h3>${m.order.map((key,i)=>`<div><label><input class="main-section-check" type="checkbox" data-key="${key}" ${m.visible[key]?'checked':''}>${{live:'자체 라이브',featured:'추천 판매 상품',shops:'기관 쇼핑몰',new:'새로 등록된 상품',story:'브랜드·나눔 이야기'}[key]}</label><span>${btn('main-section-move','↑','pill-btn',`data-index="${i}" data-dir="-1"`)}${btn('main-section-move','↓','pill-btn',`data-index="${i}" data-dir="1"`)}</span></div>`).join('')}</div><form id="main-operation-form" class="form-box mt-20">${field('메인 공지 문구','notice',m.notice,'text','maxlength="150"')}<label class="check-line"><input name="noticeOn" type="checkbox" ${m.noticeOn?'checked':''}>메인 공지 노출</label><h3>메인 추천 상품</h3><p class="small muted">선택하지 않으면 판매 중인 추천 상품을 자동으로 보여 줍니다.</p>${db.products.map(p=>`<label class="check-line"><input name="featured" value="${p.id}" type="checkbox" ${m.featured.includes(p.id)?'checked':''}>${esc(p.name)} · ${esc(org(p.org).name)}</label>`).join('')}<h3 class="mt-20">추천 기관 쇼핑몰</h3>${db.orgs.map(o=>`<label class="check-line"><input name="featuredShops" value="${o.id}" type="checkbox" ${m.featuredShops.includes(o.id)?'checked':''}>${esc(o.name)}</label>`).join('')}<button class="primary-btn green full">메인 운영 설정 저장</button></form><div class="button-group mt-20">${btn('merchant-section','배너 문구 관리','secondary-btn','data-section="campaigns"')}${btn('merchant-section','배너·여백 이미지 관리','secondary-btn','data-section="site-design"')}</div>`}
function sellCard(p){return `<article class="product-card"><a href="#/product/${p.id}" class="product-image"><img src="${productPhoto(p)}" alt="${esc(p.name)}" loading="lazy"><span class="product-label">${p.stock?'판매 상품':'품절'}</span>${p.recommended?'<span class="product-recommend-tag">PICK</span>':''}</a>${btn('wish',icon('heart'),'wish-btn '+(db.wishes.includes(p.id)?'on':''),`data-id="${p.id}" aria-label="${esc(p.name)} 찜" aria-pressed="${db.wishes.includes(p.id)}"`)}<div class="product-body"><a href="#/institution/${p.org}" class="product-org">${icon('shop')}${esc(org(p.org).name)}</a><a href="#/product/${p.id}"><h3>${esc(p.name)}</h3></a><div class="price">${p.original>p.price?`<span class="discount">${Math.round((1-p.price/p.original)*100)}%</span>`:''}${money(p.price)}<small>원</small></div><p class="product-note">${esc(p.brand||p.condition||'기관 쇼핑몰 판매 상품')}${p.variants.length?' · 옵션 선택':''}</p></div></article>`}
function filterForMall(id){return mallFilters[id]??={root:'',child:'',leaf:'',q:'',sort:'추천순',page:1,banner:0}}
function catalogChips(id){const f=filterForMall(id),list=MarketCore.categories(db,id).filter(c=>c.visible);const root=list.filter(c=>!c.parent),children=list.filter(c=>c.parent===f.root),leaves=list.filter(c=>c.parent===f.child);return `<div class="shop-catalog-navigation"><div class="chips">${btn('mall-category','전체 상품','chip '+(!f.root?'active':''),`data-org="${id}" data-id="" data-depth="root"`)}${root.map(c=>btn('mall-category',esc(c.name),'chip '+(f.root===c.id?'active':''),`data-org="${id}" data-id="${c.id}" data-depth="root"`)).join('')}</div>${f.root&&children.length?`<div class="subcategory-chips">${btn('mall-category','전체',''+(!f.child?'active':''),`data-org="${id}" data-id="" data-depth="child"`)}${children.map(c=>btn('mall-category',esc(c.name),f.child===c.id?'active':'',`data-org="${id}" data-id="${c.id}" data-depth="child"`)).join('')}</div>`:''}${f.child&&leaves.length?`<div class="subcategory-chips third-level">${btn('mall-category','전체',''+(!f.leaf?'active':''),`data-org="${id}" data-id="" data-depth="leaf"`)}${leaves.map(c=>btn('mall-category',esc(c.name),f.leaf===c.id?'active':'',`data-org="${id}" data-id="${c.id}" data-depth="leaf"`)).join('')}</div>`:''}</div>`}
function mallProductsSection(o){const id=o.id,f=filterForMall(id),selected=f.leaf||f.child||f.root,ids=selected?MarketCore.descendants(db,id,selected):null;let ps=publicProducts(id).filter(p=>(!ids||ids.has(p.categoryId))&&(!f.q||(p.name+p.brand).toLowerCase().includes(f.q.toLowerCase())));if(f.sort==='낮은 가격순')ps.sort((a,b)=>a.price-b.price);if(f.sort==='높은 가격순')ps.sort((a,b)=>b.price-a.price);if(f.sort==='최신 등록순')ps.sort((a,b)=>b.createdAt.localeCompare(a.createdAt));const pages=Math.max(1,Math.ceil(ps.length/8));f.page=Math.min(f.page,pages);return `<section class="mall-products-section"><div class="section-heading"><div><p class="section-overline">A THOUGHTFUL WAY TO SHOP</p><h2>우리 기관의 판매 상품<small>취향에 맞는 좋은 상품을 만나 보세요.</small></h2></div></div>${catalogChips(id)}<form id="mall-product-search" data-org="${id}" class="shop-inline-search">${icon('search')}<input name="q" placeholder="이 쇼핑몰의 상품 검색" value="${esc(f.q)}" aria-label="기관몰 상품 검색"><button aria-label="기관몰 상품 검색 실행">${icon('arrow')}</button></form><div class="sort-row"><span>판매 상품 ${ps.length}개</span><select id="mall-product-sort" data-org="${id}" aria-label="기관몰 상품 정렬">${['추천순','최신 등록순','낮은 가격순','높은 가격순'].map(s=>`<option ${f.sort===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="product-grid">${ps.slice((f.page-1)*8,f.page*8).map(productCard).join('')||empty('아직 표시할 상품이 없어요','다른 카테고리를 선택하거나 검색어를 바꿔 주세요.',btn('mall-filter-clear','전체 상품 보기','secondary-btn',`data-org="${id}"`))}</div>${pages>1?`<div class="shop-pagination">${Array.from({length:pages},(_,i)=>btn('mall-product-page',String(i+1),f.page===i+1?'active':'',`data-page="${i+1}" data-org="${id}"`)).join('')}</div>`:''}</section>`}
function salesTransparency(o){const rows=MarketCore.orderRows(db,{role:'admin'},o.id).filter(r=>!['취소 완료','반품 완료'].includes(r.fulfillment.status)),gross=rows.reduce((n,r)=>n+r.merchandise,0),settled=db.settlements.filter(s=>s.org===o.id&&s.orderRefs&&s.status==='정산 완료').reduce((n,s)=>n+s.net,0);return `<div class="section-heading"><div><p class="section-overline">SHOPPING WITH A PURPOSE</p><h2>상품의 가치가 이어집니다.</h2></div></div><div class="stat-grid">${statCard('상품 판매금액',won(gross),'체험 주문 · 배송비 제외',true)}${statCard('정산 완료금액',won(settled),'주문 연결 정산 기준')}</div><div class="report-card"><h3>주문부터 기관 정산까지</h3>${timeline(['상품 주문과 결제','기관의 상품 준비','주문 상품 배송','구매 확정과 판매 집계','기관 정산과 활동 공유'])}</div>${note('이 페이지는 체험 주문의 판매·정산 집계를 보여 줍니다. 실제 결제 및 기부 실적이 아닙니다.')}`}
function shopGoodsTab(o){const s=shopSettings(o.id);if(s.status!=='운영 중')return empty('쇼핑몰을 준비하고 있어요','더 좋은 상품과 함께 찾아오겠습니다.');return s.sectionOrder.filter(key=>s.sectionVisible[key]).map(key=>{if(key==='products')return mallProductsSection(o);if(key==='featured'){const ps=publicProducts(o.id).filter(p=>p.recommended);return ps.length?`<section class="mall-featured-products"><div class="section-heading"><div><p class="section-overline">OUR STORE PICKS</p><h2>기관이 고른 추천 상품</h2></div><span class="mall-pick-mark">✳</span></div><div class="product-grid">${ps.slice(0,4).map(productCard).join('')}</div></section>`:''}return `<section class="mall-story-preview"><img src="${asset('community')}" alt="마음이 이어지는 기관 이야기" loading="lazy"><div><small>THE STORY BEHIND OUR STORE</small><h3>상품 너머의<br>따뜻한 이야기.</h3><p>${esc(o.description)}</p>${btn('org-tab','기관 이야기 보기 '+icon('arrow'),'text-link','data-tab="intro" data-scroll="true"')}</div></section>`}).join('')}
function institutionHeroInner(o){const s=shopSettings(o.id),d=designFor('org:'+o.id),f=filterForMall(o.id),ids=s.bannerIds.length?s.bannerIds:[d.bannerId];f.banner=f.banner%ids.length;const slot=d.banners.find(x=>x.id===ids[f.banner])||selectedBanner(d);return `<img src="${mediaSource(slot)}" alt="${esc(slot.alt)}" style="object-position:${slot.x}% ${slot.y}%"><div class="mall-hero-gradient"></div><div class="mall-hero-copy"><span>SHOP WITH A LITTLE HEART</span><h1>${esc(o.tag)}</h1><p>기관이 준비한 좋은 상품, 오늘의 기분 좋은 쇼핑.</p></div><span class="mall-hero-label">${icon('shop')} ${esc(o.name)} 쇼핑몰</span>${ids.length>1?`<div class="mall-banner-controls">${btn('mall-banner-step',icon('back'),'',`data-org="${o.id}" data-step="-1" aria-label="이전 기관몰 배너"`)}<span>${f.banner+1} / ${ids.length}</span>${btn('mall-banner-step',icon('chevron'),'',`data-org="${o.id}" data-step="1" aria-label="다음 기관몰 배너"`)}</div>`:''}`}
function marketplaceHome(){const m=db.market.main,ps=publicProducts(),featured=(m.featured.length?m.featured.map(product).filter(p=>MarketCore.publicProduct(db,p)):ps.filter(p=>p.recommended).length?ps.filter(p=>p.recommended):ps).slice(0,6),shops=(m.featuredShops.length?db.orgs.filter(o=>m.featuredShops.includes(o.id)):db.orgs).filter(o=>shopSettings(o.id).status==='운영 중');const sections={live:()=>`<section class="section"><div class="section-heading"><div><p class="section-overline">LIVE FROM BANGGEUT</p><h2>함께 고르는 즐거움</h2></div><a class="text-link" href="#/live">라이브 보기 ${icon('chevron')}</a></div><a class="live-card" href="#/live"><img src="${asset('bazaar')}" alt="방긋마켓 자체 라이브 바자회"><span class="live-tag">LIVE PREVIEW</span><div class="live-card-copy"><small>방긋마켓 자체 운영 라이브</small><h3>${esc(db.live.title)}</h3><p>기관의 좋은 상품을 생생하게 만나 보세요.</p></div><span class="play-button">${icon('play')}</span></a></section>`,featured:()=>`<section class="section"><div class="section-heading"><div><p class="section-overline">GOOD FINDS, GOOD CHOICES</p><h2>오늘의 기분 좋은 발견<small>기관 쇼핑몰에서 만나는 추천 상품</small></h2></div><a class="text-link" href="#/shop">전체 상품 ${icon('chevron')}</a></div><div class="chips">${['전체',...allRootNames().slice(0,6)].map(c=>btn('home-product-category',c,'chip '+(homeCategory===c?'active':''),`data-category="${c}"`)).join('')}</div><div class="product-grid">${featured.filter(p=>homeCategory==='전체'||MarketCore.ancestors(db,p.org,p.categoryId).some(c=>c.name===homeCategory)).map(productCard).join('')||empty('상품을 준비하고 있어요','다른 카테고리의 상품을 만나 보세요.')}</div></section>`,shops:()=>`<section class="section"><div class="section-heading"><div><p class="section-overline">STORES WITH A PURPOSE</p><h2>마음에 닿는 기관 쇼핑몰</h2></div><a href="#/institutions" class="text-link">전체 보기 ${icon('chevron')}</a></div><div class="org-grid">${shops.slice(0,4).map(orgCard).join('')}</div></section>`,new:()=>`<section class="section"><div class="section-heading"><div><p class="section-overline">JUST ARRIVED</p><h2>새로 도착한 좋은 상품</h2></div></div><div class="product-grid">${ps.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,4).map(productCard).join('')}</div></section>`,story:()=>`<section class="section"><div class="story-card"><span class="section-overline">SMALL SHOPPING, BIG SMILES</span><h3>좋은 상품을 만나는 순간,<br>나눔의 이야기도 시작됩니다.</h3><p>기관이 운영하는 쇼핑몰과 방긋마켓의 자체 라이브.<br>기분 좋은 쇼핑이 기관의 활동을 응원합니다.</p><a class="text-link mt-20" href="#/impact">방긋마켓 이야기 ${icon('arrow')}</a></div><div class="join-banner" style="margin:22px 0 0"><h3>물건에 담긴 마음을<br>새로운 상품의 가치로.</h3><p>개인·기업의 현물 기부를 기관과 연결합니다.</p><a href="#/donate">현물 기부 알아보기 ${icon('arrow')}</a></div></section>`};return header()+`<section class="hero" aria-label="방긋마켓 소식">${heroHTML()}</section>${topNav('/')}${m.noticeOn?`<div class="market-announcement">${icon('heart')}${esc(m.notice)}</div>`:''}<div class="shortcuts">${[['/shop','bag','전체 상품'],['/live','live','자체 라이브'],['/institutions','shop','기관 쇼핑몰'],['/donate','gift','현물 기부'],['/my','user','마이 쇼핑']].map(([url,i,label])=>`<a class="shortcut" href="#${url}"><span class="shortcut-circle">${icon(i)}</span>${label}</a>`).join('')}</div>`+m.order.filter(k=>m.visible[k]).map(k=>sections[k]()).join('')+footer()+bottomNav()}
function marketplaceShop(){let ps=publicProducts().filter(p=>(shopCategory==='전체'||MarketCore.ancestors(db,p.org,p.categoryId).some(c=>c.name===shopCategory))&&(!shopSearch||(p.name+org(p.org).name+p.brand).toLowerCase().includes(shopSearch.toLowerCase())));if(shopSort==='low')ps.sort((a,b)=>a.price-b.price);if(shopSort==='high')ps.sort((a,b)=>b.price-a.price);return header()+topNav('/shop')+`<div class="page-head"><span class="eyebrow">EVERYDAY GOOD FINDS</span><h1>좋은 상품, 기분 좋은 쇼핑.</h1><p>기관 쇼핑몰의 판매 상품을 한곳에서 만나 보세요.</p></div><form id="search-form" class="search-box">${icon('search')}<input name="query" value="${esc(shopSearch)}" placeholder="상품명 · 기관명 검색" aria-label="상품명 또는 기관명 검색"><button aria-label="검색">${icon('arrow')}</button></form><section class="section" style="padding-top:0"><div class="chips">${['전체',...allRootNames()].map(c=>btn('shop-category',c,'chip '+(shopCategory===c?'active':''),`data-category="${c}"`)).join('')}</div><div class="sort-row"><span>판매 상품 ${ps.length}개</span><select id="product-sort" aria-label="상품 정렬"><option value="recommend">추천순</option><option value="low" ${shopSort==='low'?'selected':''}>낮은 가격순</option><option value="high" ${shopSort==='high'?'selected':''}>높은 가격순</option></select></div><div class="product-grid">${ps.map(productCard).join('')||empty('조건에 맞는 상품이 없어요','다른 검색어나 카테고리로 찾아보세요.',btn('clear-search','전체 상품 보기','secondary-btn'))}</div></section>`+footer()+bottomNav()}
function saleProductPage(rawId){const id=rawId.split('?')[0],p=product(id);if(!p||!MarketCore.publicProduct(db,p)&&!isManagedOrg(p.org))return header()+`<section class="section">${empty('현재 구매할 수 없는 상품입니다','기관 쇼핑몰의 다른 상품을 만나 보세요.','<a class="primary-btn green" href="#/shop">전체 상품 보기</a>')}</section>`+bottomNav();const s=shopSettings(p.org),variant=p.variants.find(v=>v.id===marketVariant),amount=p.price+(variant?.extra||0),available=p.variants.length?(variant?.stock||0):p.stock;return header()+`<div class="detail-photo"><img src="${productPhoto(p)}" alt="${esc(p.name)}"><a href="#/institution/${p.org}" class="back-float" aria-label="기관 쇼핑몰로">${icon('back')}</a>${btn('wish',icon('heart'),'wish-btn '+(db.wishes.includes(id)?'on':''),`data-id="${id}" aria-label="상품 찜"`)}</div><section class="detail-main"><a class="product-org" href="#/institution/${p.org}">${icon('shop')} ${esc(org(p.org).name)} 쇼핑몰</a><h1>${esc(p.name)}</h1><div class="price">${p.original>amount?`<span class="discount">${Math.round((1-amount/p.original)*100)}%</span>`:''}${won(amount)}${p.original>amount?`<del>${won(p.original)}</del>`:''}</div><p class="product-summary">${esc(p.summary)}</p><div class="detail-benefit">${icon('heart')} 이 기관의 상품을 고르는 당신의 쇼핑이<br><b>${esc(org(p.org).name)}</b>의 활동에 힘이 됩니다.</div><dl class="detail-spec"><dt>상품 분류</dt><dd>${esc(categoryPath(p))}</dd><dt>상품 상태</dt><dd>${esc(p.condition)}</dd><dt>상품 코드</dt><dd>${esc(p.sku)}</dd><dt>배송</dt><dd>${esc(s.dispatchDays)}<br>배송비 ${won(s.shippingFee)}${s.freeShipping?' · '+won(s.freeShipping)+' 이상 무료':''}<br>${esc(p.deliveryNote)}</dd></dl>${p.variants.filter(v=>!v.retired).length?`<label class="field">상품 옵션<select id="purchase-variant" data-id="${p.id}"><option value="">옵션을 선택해 주세요</option>${p.variants.filter(v=>!v.retired).map(v=>`<option value="${v.id}" ${marketVariant===v.id?'selected':''} ${v.stock===0?'disabled':''}>${esc(v.label)}${v.extra?' · +'+won(v.extra):''} · ${v.stock}개</option>`).join('')}</select></label>`:''}<div class="split-row"><span class="small">구매 수량${available?' · '+available+'개 구매 가능':''}</span><div class="quantity">${btn('qty-minus','−','','aria-label="수량 줄이기"')}<span>${qty}</span>${btn('qty-plus','+','',`data-max="${available||1}" aria-label="수량 늘리기"`)}</div></div>${note('주문·배송 흐름을 살펴보는 체험 상품입니다. 실제 결제나 배송은 발생하지 않습니다.')}</section><section class="section product-information"><div class="section-heading"><h2 style="font-size:18px">상품 상세 정보</h2></div><p>${esc(p.desc||'상품 상세 정보를 준비하고 있습니다.').replace(/\n/g,'<br>')}</p><details><summary>배송 및 교환·반품 안내</summary><p>${esc(s.policy)}<br>배송 일정: ${esc(s.dispatchDays)}<br>교환·반품 배송비: ${won(s.returnFee)}<br>접수 안내: ${esc(s.returnAddress)}</p></details><details><summary>판매 기관·고객센터</summary><p>${esc(org(p.org).name)}<br>${esc(s.phone)}<br>${esc(s.hours)}</p></details><div class="section-heading mt-20"><h2 style="font-size:18px">상품 문의</h2>${btn('product-inquiry','문의하기','pill-btn',`data-id="${id}"`)}</div>${db.market.inquiries.filter(q=>q.productId===id&&(AccountCore.owns(db,q)||q.status==='답변 완료')).map(q=>`<details><summary>${esc(q.title)} · ${esc(q.status)}</summary><p>${esc(q.body)}<br><b>기관 답변</b><br>${esc(q.answer||'기관에서 확인하고 있습니다.')}</p></details>`).join('')||'<p class="small muted">상품에 관해 궁금한 점을 남겨 주세요.</p>'}</section><div class="purchase-bar">${btn('add-cart',icon('cart'),'secondary-btn',`data-id="${id}" aria-label="장바구니 담기" ${p.stock&&p.saleStatus==='판매 중'?'':'disabled'}`)}${btn('buy',p.stock&&p.saleStatus==='판매 중'?won(amount*qty)+' · 구매 체험':'현재 구매 불가','primary-btn',`data-id="${id}" ${p.stock&&p.saleStatus==='판매 중'?'':'disabled'}`)}</div>`+bottomNav()}
function commerceCart(checkout=false){let q,error='';try{q=MarketCore.quote(db,db.cart,checkoutCoupon)}catch(e){error=e.message}return header()+`<div class="page-head"><div class="eyebrow">${checkout?'YOUR THOUGHTFUL ORDER':'YOUR SHOPPING BAG'}</div><h1>${checkout?'주문서 작성':'장바구니'}</h1><p>기관별로 상품을 준비하고 배송해 드리는 흐름을 체험해 보세요.</p></div><section class="section" style="padding-top:0">${!db.cart.length?empty('아직 담은 상품이 없어요','기관 쇼핑몰에서 마음에 드는 상품을 골라 보세요.','<a class="primary-btn green" href="#/shop">상품 둘러보기</a>'):db.cart.map((c,index)=>{const p=product(c.id);return p?`<div class="cart-row"><img src="${productPhoto(p)}" alt="${esc(p.name)}"><div class="cart-row-main"><a class="product-org" href="#/institution/${p.org}">${esc(org(p.org).name)}</a><h3>${esc(p.name)}</h3><small>${esc(p.variants.find(v=>v.id===c.variantId)?.label||'기본 옵션')}</small><div class="price">${won((p.price+(p.variants.find(v=>v.id===c.variantId)?.extra||0))*c.qty)}</div>${!checkout?`<div class="quantity">${btn('cart-item-step','−','',`data-index="${index}" data-delta="-1" aria-label="수량 줄이기"`)}<span>${c.qty}</span>${btn('cart-item-step','+','',`data-index="${index}" data-delta="1" aria-label="수량 늘리기"`)}</div>`:`<span class="small muted">${c.qty}개</span>`}</div>${btn('cart-item-remove',icon('close'),'icon-btn',`data-index="${index}" aria-label="상품 삭제"`)}</div>`:''}).join('')}${error?note(esc(error),true):''}${db.cart.length?`<div class="coupon-select-box"><label class="field">사용할 쿠폰<select id="checkout-coupon" aria-label="구매 쿠폰 선택"><option value="">쿠폰 사용 안 함</option>${db.market.coupons.filter(c=>c.active&&(!c.org||db.cart.some(item=>product(item.id)?.org===c.org))).map(c=>`<option value="${c.id}" ${checkoutCoupon===c.id?'selected':''}>${esc(c.name)} · ${c.type==='percent'?c.amount+'%':won(c.amount)} 할인</option>`).join('')}</select></label></div>`:''}${q?`<div class="summary-box"><div class="summary-line"><span>상품 금액</span><span>${won(q.subtotal)}</span></div><div class="summary-line"><span>쿠폰 할인</span><span style="color:var(--coral)">−${won(q.discount)}</span></div>${q.groups.map(g=>`<div class="summary-line"><span>${esc(org(g.org).short||org(g.org).name)} 배송비</span><span>${g.shipping?won(g.shipping):'무료'}</span></div>`).join('')}<div class="summary-line total"><span>총 주문 금액</span><span>${won(q.total)}</span></div></div>${checkout?`<form id="merchant-checkout-form" class="form-box mt-20"><h3>수령인과 배송지</h3><div class="field-row">${field('받는 분','name','박방긋','text','required maxlength="40"')}${field('연락처 · 체험 번호','phone','010-0000-0000','text','maxlength="30"')}</div>${field('배송지 · 체험 주소','address','서울시 나눔구 방긋로 12 (예시)','text','required maxlength="200"')}${field('배송 요청사항','memo','','text','maxlength="200"')}${selectField('결제 방법 · 체험','payment',[['카드 체험','카드 결제 체험'],['계좌 체험','계좌 결제 체험']],'카드 체험')}<label class="check-line"><input type="checkbox" required>실제 결제·배송 없이 체험 주문을 생성하는 데 동의합니다.</label><p class="small muted">실제 개인정보나 결제 정보를 입력하지 마세요.</p><button class="primary-btn full green">${won(q.total)} · 주문 체험 완료</button></form>`:`<a href="#/checkout" class="primary-btn full green mt-20">주문서 작성 ${icon('arrow')}</a>`}`:''}</section>`+bottomNav()}
function buyerOrderList(orders){return orders.length?`<div class="data-list">${orders.map(o=>`<div class="data-row"><img src="${itemPhoto(o.items[0])}" alt="${esc(o.items[0].name)}"><div class="data-row-content"><p>${esc(o.id)} · ${esc(o.date)}</p><h3>${esc(o.items[0].name)}${o.items.length>1?' 외 '+(o.items.length-1)+'종':''}</h3><strong>${won(o.total)}</strong><p>${o.fulfillments.map(f=>esc(org(f.org).short||org(f.org).name)+' · '+esc(f.status)).join('<br>')}</p></div><div class="data-row-side">${btn('order-detail','주문 상세','',`data-id="${o.id}"`)}</div></div>`).join('')}</div>`:empty('아직 주문 내역이 없어요','기관 쇼핑몰의 상품을 둘러보세요.','<a class="secondary-btn" href="#/shop">상품 보기</a>')}
function buyerOrderDetail(id){const order=db.orders.find(o=>o.id===id);if(!order||!AccountCore.owns(db,order)&&db.role!=='admin')return;openModal('나의 주문 상세',`<div class="order-detail-id"><small>주문번호</small><strong>${esc(order.id)}</strong><p>총 주문금액 ${won(order.total)}</p></div>${order.fulfillments.map(f=>`<div class="report-card"><div class="split-row"><h3>${esc(org(f.org).name)}</h3>${status(f.status)}</div>${order.items.filter(i=>i.org===f.org).map(i=>`<p class="small">${esc(i.name)} · ${esc(i.variantLabel)} ${i.qty}개</p>`).join('')}<p class="small muted">${esc(f.carrier)} · ${esc(f.tracking||'운송장 등록 전')}<br>${esc(order.address)}</p>${order.mine?`<div class="button-group">${f.status==='배송 완료'?btn('buyer-confirm','구매 확정','primary-btn green',`data-order="${id}" data-org="${f.org}"`):''}${['신규 주문','상품 준비 중','배송 중','배송 완료','구매 확정'].includes(f.status)?btn('buyer-claim','취소·교환·반품 요청','secondary-btn',`data-order="${id}" data-org="${f.org}"`):''}</div>`:''}</div>`).join('')}<div class="small muted">체험 주문입니다. 실제 결제·배송·환불은 진행되지 않습니다.</div>`,true)}
function allRootNames(){return [...new Set(db.orgs.flatMap(o=>MarketCore.categories(db,o.id).filter(c=>!c.parent&&c.visible).map(c=>c.name)))]}
function merchantExport(kind){let rows;if(kind==='products')rows=[['상품 코드','기관','상품명','카테고리','판매가','재고','판매상태'],...scopedProductList().map(p=>[p.sku,org(p.org).name,p.name,categoryPath(p),p.price,p.stock,p.saleStatus])];else if(kind==='settlements')rows=[['정산번호','기관','상품금액','운영비용','조정금액','정산액','상태'],...db.settlements.filter(s=>merchantOrgIds().includes(s.org)).map(s=>[s.id,org(s.org).name,s.gross,s.fee,s.adjustment||0,s.net,s.status])];else rows=[['주문번호','기관','수령인','상품','옵션','상품금액','배송비','주문합계','배송상태','택배사','운송장'],...scopedOrderRows().map(r=>[r.orderId,org(r.org).name,r.name,r.items.map(i=>i.name+' x '+i.qty).join(' / '),r.items.map(i=>i.variantLabel).join(' / '),r.merchandise,r.fulfillment.shipping,r.total,r.fulfillment.status,r.fulfillment.carrier,r.fulfillment.tracking])];download('banggeut-'+kind+'-demo.csv','\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n'));toast('현재 기관과 필터 범위의 CSV를 다운로드했습니다.')}
