function shippingModal(){openModal('운송장 일괄 등록',`<p>한 줄에 하나씩, 아래 형식으로 입력해 주세요.</p><div class="bulk-import-example">주문번호, 기관명, 택배사, 운송장번호</div><form id="bulk-shipping-form"><label class="field">운송장 등록 목록<textarea name="lines" required rows="7" placeholder="B-주문번호, 초록나무 복지관, CJ대한통운, DEMO123456"></textarea></label><p class="small muted">상품 준비 중인 주문의 상태를 배송 중으로 변경합니다. 실제 택배 접수는 이루어지지 않습니다.</p><button class="primary-btn green full">입력 목록 확인</button></form>`,true)}
function parseShipping(lines){const rows=lines.split('\n').map(x=>x.trim()).filter(Boolean).map(line=>{const [orderId,orgName,carrier,tracking]=line.split(',').map(s=>s.trim());const orgId=db.orgs.find(o=>o.id===orgName||o.name===orgName)?.id;MarketCore.guard(merchantActor(),orgId);if(!orderId||!carrier||!tracking)throw Error('주문번호·기관·택배사·운송장을 모두 입력해 주세요.');return {orderId,org:orgId,carrier,tracking}});if(!rows.length)throw Error('운송장 목록을 입력해 주세요.');if(new Set(rows.map(r=>r.orderId+':'+r.org)).size!==rows.length)throw Error('같은 기관 주문이 중복되었습니다.');const clone=structuredClone(db);for(const r of rows)MarketCore.updateFulfillment(clone,merchantActor(),r.orderId,r.org,{status:'배송 중',carrier:r.carrier,tracking:r.tracking});return rows}
