 const previousConsole=consolePage;consolePage=function(){const html=previousConsole();const supported=['dashboard','products','goods','categories','inventory','orders','shipping','sales','analytics','reports','claims','settlements','mall','coupons','customers','institutions','shoppers'];return canOperate()&&supported.includes(consoleSection)?html.replace('<section class="section" id="console-content">',scopePanel()+'<section class="section" id="console-content">'):html};
