 addToCart=function(id,count=qty){try{const p=product(id);if(!MarketCore.publicProduct(db,p)||p.saleStatus!=='판매 중')throw Error('현재 구매할 수 없는 상품입니다.');const variantId=p.variants.filter(v=>!v.retired).length?marketVariant:null;if(p.variants.filter(v=>!v.retired).length&&!variantId)throw Error('구매할 상품 옵션을 선택해 주세요.');const current=db.cart.find(c=>c.id===id&&(c.variantId||null)===(variantId||null));if((current?.qty||0)+count>MarketCore.productStock(p,variantId))throw Error('구매 가능한 재고를 확인해 주세요.');if(current)current.qty+=count;else db.cart.push({id,variantId,qty:count});save();return true}catch(error){toast(error.message);return false}};
 const previousRender=render;render=function(reset=false){MarketCore.ensure(db);previousRender(reset);document.querySelectorAll('.bottom-nav a').forEach(a=>{if(a.classList.contains('active'))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const inside=currentRoute.startsWith('/institution/');if(inside){const id=currentRoute.split('/')[2],s=shopSettings(org(id).id);$('#app').dataset.mallLayout=s.layout;$('#app').dataset.cardStyle=s.cardStyle;$('#app').dataset.shopTheme=s.theme;document.body.style.setProperty('--green',org(id).color)}else{document.body.style.setProperty('--green','#477560');delete $('#app').dataset.mallLayout;delete $('#app').dataset.cardStyle;delete $('#app').dataset.shopTheme}};
